import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.some.js";
import ChannelIcon from '@/components/icons/ChannelIcon.vue';
import { CHANNEL_OPTIONS } from '@/utils/channelOptions';
export default {
  name: 'UploadChannelBar',
  components: {
    ChannelIcon
  },
  props: {
    uploadChannel: {
      type: String,
      default: ''
    },
    channelName: {
      type: String,
      default: ''
    },
    availableChannels: {
      type: Object,
      default: () => ({})
    },
    currentChannelList: {
      type: Array,
      default: () => []
    }
  },
  emits: ['update:uploadChannel', 'update:channelName', 'open-settings'],
  computed: {
    channelsLoaded() {
      return Object.keys(this.availableChannels || {}).length > 0;
    },
    configuredChannelOptions() {
      return CHANNEL_OPTIONS.filter(option => {
        const channels = this.availableChannels[option.value];
        return Array.isArray(channels) && channels.length > 0;
      });
    },
    channelOptions() {
      return this.configuredChannelOptions;
    }
  },
  watch: {
    availableChannels: {
      handler() {
        this.ensureConfiguredChannelSelected();
      },
      deep: true,
      immediate: true
    }
  },
  methods: {
    selectChannel(value) {
      if (value === this.uploadChannel) {
        return;
      }
      // 切换渠道类型后由父组件的 watch 负责校验并清空失效的渠道名称
      this.$emit('update:uploadChannel', value);
    },
    ensureConfiguredChannelSelected() {
      if (this.channelOptions.length === 0) {
        return;
      }
      if (this.channelOptions.some(option => option.value === this.uploadChannel)) {
        return;
      }
      this.$emit('update:uploadChannel', this.channelOptions[0].value);
    }
  }
};